const $=id=>document.getElementById(id),cv=$('view'),ctx=cv.getContext('2d');
let pattern=[['K','K'],['K','K']],yarns=Array.from({length:32},(_,i)=>i%2?'#a38a45':'#454744'),brush='K',mode='swatch',lens={x:.55,y:.55},pan={x:0,y:0},history=[],painting=false;
const names={K:'Knit',T:'Tuck',M:'Miss'};
function symbol(a){return '<svg viewBox="0 0 30 26" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">'+({K:'<path d="M5 3L15 23L25 3"/>',T:'<path d="M6 23V12C6 0 24 0 24 12V23"/>',M:'<path d="M4 13H26"/>'}[a])+'</svg>'}
function validPattern(p){return Array.isArray(p)&&p.length>=2&&p.length<=32&&Array.isArray(p[0])&&p[0].length>=2&&p[0].length<=24&&p.every(row=>Array.isArray(row)&&row.length===p[0].length&&row.every(a=>['K','T','M'].includes(a)))}
function trackGroups(p){let signatures=[],map=[];for(let n=0;n<p[0].length;n++){let sig=p.map(r=>r[n]).join(''),t=signatures.indexOf(sig);if(t<0){t=signatures.length;signatures.push(sig)}map.push(t)}return {map,signatures}}
function record(){history.push(JSON.stringify(pattern));if(history.length>40)history.shift();$('undo').disabled=false}
function data(){return {version:3,pattern,yarns,jerseyStudy:$('jerseyStudy').checked,colourMode:$('colours').value,color:$('color').value}}
let saveTimer, renderFrame, camDirty=false;
function flushSave(){clearTimeout(saveTimer);try{localStorage.setItem('knit-custom-v3',JSON.stringify(data()));$('saveStatus').textContent='Saved on this device'}catch{$('saveStatus').textContent='Autosave unavailable. Use Save design to keep your work.'}}
function persist(){restoreFailed=false;clearTimeout(saveTimer);$('saveStatus').textContent='Saving…';saveTimer=setTimeout(flushSave,250)}
function draw(){if(renderFrame)return;renderFrame=requestAnimationFrame(()=>{renderFrame=null;if(camDirty){camUI();camDirty=false}drawNow()})}
window.addEventListener('pagehide',()=>{if(!restoreFailed)flushSave()});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(!restoreFailed)flushSave();}});

function applyData(d){if(!validPattern(d.pattern))throw Error('Invalid pattern');pattern=d.pattern.map(r=>[...r]);$('jerseyStudy').checked=d.jerseyStudy===true;if(Array.isArray(d.yarns)&&d.yarns.length>=d.pattern.length&&d.yarns.every(c=>/^#[0-9a-f]{6}$/i.test(c)))d.yarns.forEach((c,i)=>{if(i<32)yarns[i]=c});if(['two','solid'].includes(d.colourMode))$('colours').value=d.colourMode;if(/^#[0-9a-f]{6}$/i.test(d.color))$('color').value=d.color}
function setBrush(a){brush=a;document.querySelectorAll('[data-brush]').forEach(b=>{b.classList.toggle('active',b.dataset.brush===a);b.setAttribute('aria-pressed',String(b.dataset.brush===a))});$('fill').textContent='Fill with '+names[a]}
function cellContent(a){return symbol(a)+'<small>'+a+'</small>'}
function updateCell(r,n){let a=pattern[r][n],b=$('grid').querySelector('[data-r="'+r+'"][data-n="'+n+'"]');b.className='stitch '+a;b.innerHTML=cellContent(a);b.setAttribute('aria-label','Feeder '+(r+1)+' needle '+(n+1)+' '+names[a])}
function paint(r,n){if(pattern[r][n]===brush)return;pattern[r][n]=brush;updateCell(r,n);$('preset').value='custom';camDirty=true;draw();persist()}
function camUI(){let g=trackGroups(pattern);$('trackMap').textContent='Needle track arrangement: '+g.map.map(t=>t+1).join(', ');$('cams').innerHTML='<table><tr><th>Track</th>'+pattern.map((_,r)=>'<th>F'+(r+1)+'</th>').join('')+'</tr>'+g.signatures.map((sig,t)=>'<tr><th>'+(t+1)+'</th>'+[...sig].map(a=>'<td title="'+names[a]+'">'+a+'</td>').join('')+'</tr>').join('')+'</table>';let cap=+$('machineTracks').value;$('compatibility').textContent=g.signatures.length+' track(s) required. '+(g.signatures.length<=cap?'Fits the selected '+cap+'-track limit by action sequence.':'Exceeds the selected '+cap+'-track limit. Change the repeat or machine selection.');$('compatibility').style.color=g.signatures.length>cap?'#a54430':'#245548'}
function ui(){let cols=pattern[0].length;$('needles').value=cols;if(![...$('rows').options].some(o=>+o.value===pattern.length))$('rows').add(new Option(pattern.length,pattern.length));$('rows').value=pattern.length;$('step').max=pattern.length;if(+$('step').value>pattern.length)$('step').value=1;
 $('brushes').innerHTML=['K','T','M'].map(a=>'<button data-brush="'+a+'" aria-label="Paint '+names[a]+'">'+symbol(a)+'<b>'+names[a]+'</b><br><small>'+a+'</small></button>').join('');document.querySelectorAll('[data-brush]').forEach(b=>b.onclick=()=>setBrush(b.dataset.brush));setBrush(brush);
 $('grid').innerHTML='<table><tr><th>F / N</th>'+Array.from({length:cols},(_,n)=>'<th>'+(n+1)+'</th>').join('')+'</tr>'+pattern.map((row,r)=>'<tr><th>'+(r+1)+'</th>'+row.map((a,n)=>'<td><button class="stitch '+a+'" data-r="'+r+'" data-n="'+n+'" aria-label="Feeder '+(r+1)+' needle '+(n+1)+' '+names[a]+'">'+cellContent(a)+'</button></td>').join('')+'</tr>').join('')+'</table>';
 $('grid').querySelectorAll('button').forEach(b=>{b.onpointerdown=e=>{if(e.button!==0||window.editorMove)return;e.preventDefault();b.focus({preventScroll:true});record();painting=true;paint(+b.dataset.r,+b.dataset.n)};b.onkeydown=e=>{const directions={ArrowUp:[-1,0],ArrowDown:[1,0],ArrowLeft:[0,-1],ArrowRight:[0,1]};if(directions[e.key]){e.preventDefault();const [dr,dn]=directions[e.key];$('grid').querySelector('[data-r="'+(+b.dataset.r+dr)+'"][data-n="'+(+b.dataset.n+dn)+'"]')?.focus();return}if(['k','t','m'].includes(e.key.toLowerCase())){e.preventDefault();setBrush(e.key.toUpperCase());record();paint(+b.dataset.r,+b.dataset.n);return}if(e.key==='Enter'||e.key===' '){e.preventDefault();record();paint(+b.dataset.r,+b.dataset.n)}}});
 $('feederColors').innerHTML='<div class="row">'+pattern.map((_,r)=>'<label class="hint">F'+(r+1)+' <input type="color" data-f="'+r+'" value="'+yarns[r]+'"></label>').join('')+'</div>';$('feederColors').querySelectorAll('input').forEach(b=>b.oninput=()=>{yarns[+b.dataset.f]=b.value;draw();persist()});$('undo').disabled=!history.length;camUI();
}
document.addEventListener('pointermove',e=>{if(!painting||window.editorMove)return;let b=document.elementFromPoint(e.clientX,e.clientY)?.closest('#grid button[data-r]');if(b)paint(+b.dataset.r,+b.dataset.n)});document.addEventListener('pointerup',()=>painting=false);document.addEventListener('pointercancel',()=>painting=false);
let lastSummary='';
function drawNow(){let swatch=mode==='swatch';$('space').disabled=$('jerseyStudy').checked&&pattern.every(row=>row.every(a=>a==='K'));$('relief').disabled=swatch;$('highlight').disabled=swatch;$('side').disabled=!swatch;$('jerseyMessage').textContent=$('jerseyStudy').checked?(pattern.every(row=>row.every(a=>a==='K'))?'Study active: 30 WPI × 42 CPI · 3.0 mm loop length · estimated cotton surface.':'Study paused: this model supports all-knit designs. Your K/T/M preview is shown.'):'Study off: original K/T/M preview.';paintPreview(ctx,{pattern,mode,jerseyStudy:$('jerseyStudy').checked,garmentType:$('garmentType').value,garmentSide:$('garmentSide').value,yarns:$('colours').value==='two'?yarns:null,side:$('side').value,lens,color:$('color').value,thickness:+$('thick').value,spacing:+$('space').value,zoom:+$('zoom').value,relief:+$('relief').value,highlight:$('highlight').checked,selected:+$('step').value-1,pan});let summary=JSON.stringify(pattern);if(summary===lastSummary)return;lastSummary=summary;let bad=Array.from({length:pattern[0].length},(_,n)=>n).filter(n=>!pattern.some(row=>row[n]==='K'));$('status').textContent=bad.length?'Needle '+bad.map(n=>n+1).join(', ')+' never knits in this repeat. Held loops are not released.':'Every needle knits within the repeat. Check long tuck/miss sequences against the yarn and machine before sampling.'}
function update(){ui();draw();persist()}
function resize(rows,cols){record();pattern=Array.from({length:rows},(_,r)=>Array.from({length:cols},(_,n)=>pattern[r]?.[n]||'K'));$('preset').value='custom';update()}
function applySize(){let n=Number($('needles').value),r=Number($('rows').value);if(!Number.isInteger(n)||n<2||n>24){$('editorMessage').textContent='Choose 2–24 needles.';return}if(r<pattern.length||n<pattern[0].length){if(!confirm('Shrinking removes stitches outside the new size. You can Undo this change. Continue?'))return}if(r!==pattern.length||n!==pattern[0].length)resize(r,n);$('editorMessage').textContent='Size applied: '+n+' needles × '+r+' feeders.'}
$('applySize').onclick=applySize;
$('preset').onchange=e=>{record();let v=e.target.value;if(v==='custom'){pattern=pattern.map(row=>row.map(()=> 'K'))}else pattern=v==='jersey'?[['K','K'],['K','K']]:v==='miss'?[['K','M'],['K','K']]:v==='pique'?[['K','T'],['K','K'],['T','K'],['K','K']]:[['K','T'],['K','K']];update()};
$('new').onclick=()=>{record();pattern=pattern.map(row=>row.map(()=> 'K'));$('preset').value='custom';update();$('editorMessage').textContent='New custom repeat ready. Select a stitch and paint.'};$('undo').onclick=()=>{if(history.length){pattern=JSON.parse(history.pop());$('preset').value='custom';update()}};$('fill').onclick=()=>{record();pattern=pattern.map(row=>row.map(()=>brush));$('preset').value='custom';update()};$('machineTracks').onchange=camUI;
['jerseyStudy','color','colours','side','thick','space','step','zoom','relief','highlight','garmentType','garmentSide'].forEach(id=>$(id).oninput=()=>{draw();persist()});['swatch','fabric','loops'].forEach(m=>$(m).onclick=()=>{mode=m;['swatch','fabric','loops'].forEach(v=>$(v).classList.toggle('active',v===m));draw()});$('reset').onclick=()=>{record();pattern=[['K','T'],['K','K']];$('preset').value='tuck';update()};$('fit').onclick=()=>{pan={x:0,y:0};$('zoom').value=1;draw()};
let drag=null;cv.style.touchAction='none';cv.style.cursor='grab';cv.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};cv.setPointerCapture(e.pointerId)};cv.onpointermove=e=>{if(!drag){let rect=cv.getBoundingClientRect();lens={x:(e.clientX-rect.left)/rect.width,y:(e.clientY-rect.top)/rect.height};if(mode==='swatch')draw();return}let ratio=cv.width/cv.getBoundingClientRect().width;pan.x=drag.px+(e.clientX-drag.x)*ratio;pan.y=drag.py+(e.clientY-drag.y)*ratio;draw()};cv.onpointerup=cv.onpointercancel=()=>drag=null;
function download(url,name){let a=document.createElement('a');a.href=url;a.download=name;a.click()}
$('exportGarment').onclick=async()=>{drawNow();await previewReady();download($('garmentView').toDataURL(),'knit-garment.png')};
$('export').onclick=async()=>{if(renderFrame){cancelAnimationFrame(renderFrame);renderFrame=null}drawNow();await previewReady();download(cv.toDataURL(),'knit-preview.png')};$('save').onclick=()=>{let url=URL.createObjectURL(new Blob([JSON.stringify(data(),null,2)],{type:'application/json'}));download(url,'custom-knit-design.json');setTimeout(()=>URL.revokeObjectURL(url),1000)};$('load').onchange=async e=>{try{if(!e.target.files[0])return;let d=JSON.parse(await e.target.files[0].text());if(!validPattern(d.pattern))throw Error();record();applyData(d);$('preset').value='custom';update();$('editorMessage').textContent='Design loaded.'}catch{$('editorMessage').textContent='Choose a saved design JSON with 2–32 feeders, 2–24 needles and K/T/M cells.'}};
let restoreFailed=false;try{let d=JSON.parse(localStorage.getItem('knit-custom-v3'));if(d)applyData(d);else{let p=JSON.parse(localStorage.getItem('knit-v1'));if(validPattern(p))pattern=p}}catch{$('editorMessage').textContent='Saved data could not be restored. The original browser data was left untouched.';document.getElementById('saveStatus').textContent='Check your saved JSON backup';restoreFailed=true} $('preset').value='custom';if(restoreFailed){ui();draw()}else update();

